-- Keybinds (merged: configs/Keybinds.conf, configs/Laptops.conf, UserConfigs/UserKeybinds.conf, UserConfigs/Laptops.conf)
-- Descriptions (old `bindd`) show up in `hyprctl binds` and are read by scripts/KeyBinds.sh.
local v = require("lua.vars")
local actions = require("lua.actions")
local mainMod, scriptsDir, userScripts, term, files = v.mainMod, v.scriptsDir, v.userScripts, v.term, v.files

-- Layout-aware window cycling: behaviour follows general.layout, scripts/ChangeLayout.sh only flips the layout
local function layout_bind(master, dwindle)
    return function()
        local action = (hl.get_config("general.layout") == "master") and master or dwindle
        if action then hl.dispatch(action) end
    end
end
hl.bind(mainMod .. " + J", layout_bind(hl.dsp.layout("cyclenext"), hl.dsp.window.cycle_next()), { description = "cycle next window" })
hl.bind(mainMod .. " + K", layout_bind(hl.dsp.layout("cycleprev"), hl.dsp.window.cycle_next({ next = false })), { description = "cycle previous window" })
hl.bind(mainMod .. " + O", layout_bind(nil, hl.dsp.layout("togglesplit")), { description = "toggle split (dwindle)" })


