-- Workspaces 1-10 on the number row: focus / move / move silently
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    local focus = hl.dsp.focus({ workspace = i })
    if i == 4 then -- Slack lives on 4: jump there and show unreads
        focus = hl.dsp.exec_cmd(scriptsDir .. "/goto-slack.sh")
    end
    hl.bind(mainMod .. " + " .. key, focus, { description = "workspace " .. i })
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }), { description = "move to workspace " .. i })
    hl.bind(mainMod .. " + CTRL + " .. key, hl.dsp.window.move({ workspace = i, follow = false }), { description = "move silently to workspace " .. i })
end

